const email = process.env.NERJA_EMAIL;
const password = process.env.NERJA_PASSWORD;
if (!email || !password) throw new Error('Set NERJA_EMAIL and NERJA_PASSWORD env vars');
return [{ json: { email, password } }];

const r = $json;
if (r.statusCode !== 200) throw new Error('Login failed: ' + r.statusCode);
const setCookie = r.headers && r.headers['set-cookie'];
const cookie = Array.isArray(setCookie) ? setCookie.join('; ') : (setCookie || '');
return [{ json: { cookie, user: r.body && r.body.user, tenant: r.body && r.body.tenant, tests: [] } }];

const r = $json;
const ctx = $('Extract Session Cookie').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const ok = r.statusCode === 200 && body.includes('Analytics') && body.includes('TOTAL EVENTS');
return [{ json: { ...ctx, tests: [...ctx.tests, { id: 'F1', name: 'Analytics: Page loads with metrics', passed: ok, detail: ok ? '✅ Analytics page shows TOTAL EVENTS metric' : '❌ Analytics metrics not visible (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F1').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasLeadsList = body.includes('Leads list') || body.includes('leads-list') || body.includes('Download CSV');
const hasAudienceStudio = body.includes('Audience Studio');
const ok = r.statusCode === 200 && hasLeadsList && hasAudienceStudio;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F2', name: 'Leads: List + Audience Studio tab visible', passed: ok, detail: ok ? '✅ Leads page shows list and Audience Studio tab' : '❌ Leads page missing components (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F2').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasFilters = body.includes('Live') && body.includes('Paused') && body.includes('Completed');
const hasCreateBtn = body.includes('Create campaign');
const ok = r.statusCode === 200 && hasFilters && hasCreateBtn;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F3', name: 'Campaigns: Filters + Create button visible', passed: ok, detail: ok ? '✅ Campaigns page has status filters and Create button' : '❌ Campaign filters or Create button missing (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F3').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasEmail = body.includes('Amazon SES') || body.includes('AutoSend') || body.includes('Resend');
const hasSMS = body.includes('Twilio');
const hasWhatsApp = body.includes('WhatsApp') || body.includes('WAAPI');
const ok = r.statusCode === 200 && hasEmail && hasSMS && hasWhatsApp;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F4', name: 'Integrations: Email, SMS, WhatsApp providers visible', passed: ok, detail: ok ? '✅ All provider categories visible' : '❌ Provider sections missing (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F4').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasWorkspace = body.includes('Workspace name') || body.includes('Workspace');
const hasApiKeys = body.includes('API keys');
const hasSaveBtn = body.includes('Save changes');
const ok = r.statusCode === 200 && hasWorkspace && hasApiKeys && hasSaveBtn;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F5', name: 'Settings: Workspace fields + API Keys tab + Save visible', passed: ok, detail: ok ? '✅ Settings page complete with all sections' : '❌ Settings fields missing (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F5').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasCurrentPlan = body.includes('CURRENT PLAN') || body.includes('Starter');
const hasUsage = body.includes('EVENTS') || body.includes('AI EMAILS');
const hasUpgrade = body.includes('Upgrade') || body.includes('Growth');
const ok = r.statusCode === 200 && hasCurrentPlan && hasUsage && hasUpgrade;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F6', name: 'Billing: Current plan + usage + upgrade options', passed: ok, detail: ok ? '✅ Billing page shows plan, usage, and upgrade options' : '❌ Billing page incomplete (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F6').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasWebsite = body.includes('NerjaTag') || body.includes('Website');
const hasKnowledgeBase = body.includes('Knowledge base');
const hasAddBtn = body.includes('Add data source');
const ok = r.statusCode === 200 && hasWebsite && hasKnowledgeBase && hasAddBtn;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F7', name: 'Data Room: NerjaTag, Knowledge Base, Add Source visible', passed: ok, detail: ok ? '✅ Data room shows all source components' : '❌ Data room missing components (status ' + r.statusCode + ')' }] } }];

const r = $json;
const prev = $('Eval F7').first().json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const hasBrowse = body.includes('Browse abandonment');
const hasCart = body.includes('Cart abandonment');
const hasCheckout = body.includes('Checkout abandonment');
const hasWelcome = body.includes('Welcome back');
const ok = r.statusCode === 200 && hasBrowse && hasCart && hasCheckout && hasWelcome;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'F8', name: 'Dashboard: 3 campaign templates + welcome message', passed: ok, detail: ok ? '✅ Dashboard shows all 3 recovery campaign templates' : '❌ Dashboard missing campaign templates (status ' + r.statusCode + ')' }] } }];

const data = $('Eval F8').first().json;
const tests = data.tests || [];
const passed = tests.filter(t => t.passed).length;
const failed = tests.filter(t => !t.passed).length;
console.log('\n╔══════════════════════════════════════════╗');
console.log('║  NERJA AI — FUNCTIONAL TESTS RESULTS     ║');
console.log('╚══════════════════════════════════════════╝');
tests.forEach(t => console.log(t.detail));
console.log('\n→ ' + passed + '/' + tests.length + ' passed | ' + failed + ' failed');
return [{ json: { suite: '04 Functional Tests', total: tests.length, passed, failed, status: failed === 0 ? 'PASS' : 'FAIL', tests, timestamp: new Date().toISOString() } }];
